import Foundation

actor DockDataEngine {
    private var hosts: [DockHostConfiguration]
    private var sessionTable = DockSessionTable()
    private var localMetadata: [LocalThreadMetadataKey: LocalThreadMetadata]

    init(
        registry: HostRegistry,
        localMetadata: [LocalThreadMetadataKey: LocalThreadMetadata] = [:]
    ) {
        self.hosts = registry.hosts
        self.localMetadata = localMetadata
        self.sessionTable.reset(hosts: registry.hosts)
    }

    func updateRegistry(_ registry: HostRegistry) {
        hosts = registry.hosts
        sessionTable.reset(hosts: registry.hosts)
    }

    func updateLocalMetadata(_ values: [LocalThreadMetadataKey: LocalThreadMetadata]) {
        localMetadata = values
    }

    func ensureHosts() {
        sessionTable.ensureHosts(hosts)
    }

    func markChecking(host: DockHostConfiguration) {
        sessionTable.markChecking(host: host)
    }

    func markFailure(_ failure: DockLoadFailure, host: DockHostConfiguration) {
        sessionTable.markFailure(failure, host: host)
    }

    func applySnapshot(
        _ update: DockStreamUpdateDTO,
        host: DockHostConfiguration
    ) -> DockSessionTableApplyResult {
        sessionTable.applySnapshot(update, host: host)
    }

    func applyUpdate(
        _ update: DockStreamUpdateDTO,
        host: DockHostConfiguration
    ) -> DockSessionTableApplyResult {
        sessionTable.applyUpdate(update, host: host)
    }

    func rowCount(for host: DockHostConfiguration) -> Int {
        sessionTable.rowCount(for: host)
    }

    func snapshot(now: @escaping @Sendable () -> Date = Date.init) -> DockSnapshot? {
        guard !hosts.isEmpty else {
            return nil
        }
        return DockRenderProjector(now: now).snapshot(
            from: sessionTable.renderInput(hosts: hosts),
            localMetadata: localMetadata
        )
    }
}

}

private func closeStreams() async {
    streamTasks.values.forEach { $0.cancel() }
    streamTasks = [:]
    let connections = streamConnections
    streamConnections = [:]
    for connection in connections.values {
        await connection.close()
    }
}

private func publishSnapshot() async {
    guard !hosts.isEmpty else {
        return
    }
    guard let snapshot = await dataEngine?.snapshot(now: now) else {
        return
    }
    state = .loaded(snapshot)
    screenStore.publish(snapshot: snapshot)
    publishConnectivity(for: state)
}

private func publishConnectivity(for state: DockStoreState) {
    if connectivityEventSink == nil {
        connectivityReporter?.reportDockState(state)
    }
    recordConnectivityFacts(for: state)
}

private func recordConnectivityFacts(for state: DockStoreState) {
    guard let connectivityEventSink else {
        return
    }
    let events = connectivityEvents(for: state)
    guard !events.isEmpty else {
        return
    }
    Task {
        for event in events {
            await connectivityEventSink.record(event)
        }
    }
}

private func connectivityEvents(for state: DockStoreState) -> [ConnectivityRuntimeEvent] {
    switch state {
    case .configurationError(let message):
        return [
            ConnectivityRuntimeEvent(
                source: .dock,
                hostID: nil,
                route: "dock/configuration",
                status: message,
                phase: .configurationError(message),
                recordedAt: now()
            )
        ]
    case .idle(let hosts):
        return hosts.map { host in
            ConnectivityRuntimeEvent(
                source: .dock,
                hostID: host.id,
                route: "dock",
                status: "idle",
                phase: .unknown,
                recordedAt: now()
            )
        }
    case .loading(let hosts):
        return hosts.map { host in
            ConnectivityRuntimeEvent(
                source: .dock,
                hostID: host.id,
                route: "dock/subscribe",
                status: "checking",
                phase: .checking,
                recordedAt: now()
            )
        }
    case .offline(let host, let message):
        return [
            ConnectivityRuntimeEvent(
                source: .dock,
                hostID: host.id,
                route: "dock/subscribe",
                status: "offline: \(message)",
                phase: .offline(message),
                recordedAt: now()
            )
        ]
    case .error(let host, let message):
        return [
            ConnectivityRuntimeEvent(
                source: .dock,
                hostID: host.id,
                route: "dock/subscribe",
                status: "error: \(message)",
                phase: .error(message),
                recordedAt: now()
            )
        ]
    case .loaded(let snapshot):
        return snapshot.hostStates.map { hostState in
            ConnectivityRuntimeEvent(
                source: .dock,
                hostID: hostState.host.id,
                route: "dock/subscribe",
                status: hostState.status.subtitle,
                phase: Self.connectivityPhase(for: hostState.status),
                recordedAt: now()
            )
        }
    }
}

private nonisolated static func connectivityPhase(
    for status: DockHostLoadStatus
) -> HostConnectivityPhase {
    switch status {
    case .checking:
        return .checking
    case .loaded(let rowCount):
        return .online("\(rowCount) sessions")
    case .partial(_, let message):
        return .partial(message)
    case .empty:
        return .online("Online, no sessions")
    case .offline(let message):
        return .offline(message)

import Foundation

public protocol DockStreamConnection: Sendable {
    func subscribe() async throws -> DockStreamUpdateDTO
    func resync() async throws -> DockStreamUpdateDTO
    func updates() -> AsyncThrowingStream<DockStreamUpdateDTO, Error>
    func close() async
}

public protocol DockStreamConnecting: Sendable {
    func connect(to host: DockHostConfiguration) async throws -> any DockStreamConnection
}

public struct AppServerDockStreamClient: DockStreamConnecting {
    private let makeClient: @Sendable (DockRelayEndpoint) -> AppServerClient
    private let observabilityStore: ClientObservabilityStore

    public init(
        observabilityStore: ClientObservabilityStore = .shared,
        makeClient: @escaping @Sendable (DockRelayEndpoint) -> AppServerClient = {
            AppServerClient(webSocketURL: $0.webSocketURL, bearerToken: nil, connectionPolicy: .liveDetail)
        }
    ) {
        self.observabilityStore = observabilityStore
        self.makeClient = makeClient
    }

    public func connect(to host: DockHostConfiguration) async throws -> any DockStreamConnection {
        let client = makeClient(host.endpoint)
        _ = try await client.connectAndInitialize(timeout: CodexDockConstants.AppServer.connectInitializeTimeout)
        return AppServerDockStreamConnection(
            client: client,
            host: host,
            observabilityStore: observabilityStore
        )
    }
}

public final class AppServerDockStreamConnection: DockStreamConnection, @unchecked Sendable {
    private let client: AppServerClient
    private let host: DockHostConfiguration
    private let observabilityStore: ClientObservabilityStore
    private let updateStream: AsyncThrowingStream<DockStreamUpdateDTO, Error>
    private let updateContinuation: AsyncThrowingStream<DockStreamUpdateDTO, Error>.Continuation
    private var notificationTask: Task<Void, Never>?

    init(
        client: AppServerClient,
        host: DockHostConfiguration,
        observabilityStore: ClientObservabilityStore = .shared
    ) {
        self.client = client
        self.host = host
        self.observabilityStore = observabilityStore
        let stream = AsyncThrowingStream<DockStreamUpdateDTO, Error>.makeStream()
        self.updateStream = stream.stream
        self.updateContinuation = stream.continuation
        self.notificationTask = Task { [client, updateContinuation, host, observabilityStore] in
            for await notification in client.notifications {
                guard notification.method == AppServerMethods.dockUpdate else {
                    continue
                }
                await observabilityStore.recordPassive(
                    route: AppServerMethods.dockUpdate,
                    configuredHostID: host.id,
                    relayHostID: nil
                )
                do {
                    guard let params = notification.params else {
                        continue
                    }
                    updateContinuation.yield(try params.decoded(as: DockStreamUpdateDTO.self))
                } catch {
                    updateContinuation.finish(throwing: AppServerClientError.responseDecoding(error.localizedDescription))
                    return
                }
            }
            updateContinuation.finish()
        }
    }

    deinit {
        notificationTask?.cancel()
        updateContinuation.finish()
    }

    public func subscribe() async throws -> DockStreamUpdateDTO {
        DockLog.dock.notice("dock stream subscribe started host_id=\(self.host.id, privacy: .public)")
        let context = AppServerRequestObservabilityContext(
            configuredHostID: host.id,
            route: AppServerMethods.dockSubscribe,
            store: observabilityStore
        )
        let response = try await client.sendRequest(
            method: AppServerMethods.dockSubscribe,
            timeout: CodexDockConstants.AppServer.defaultRequestTimeout,
            observabilityContext: context,
            as: DockStreamUpdateDTO.self
        )
        DockLog.dock.notice("dock stream subscribe finished host_id=\(self.host.id, privacy: .public) seq=\(response.seq, privacy: .public)")
        return response
    }

    public func resync() async throws -> DockStreamUpdateDTO {
        let context = AppServerRequestObservabilityContext(
            configuredHostID: host.id,
            route: AppServerMethods.dockResync,
            store: observabilityStore
        )
        return try await client.sendRequest(
            method: AppServerMethods.dockResync,
            timeout: CodexDockConstants.AppServer.defaultRequestTimeout,
            observabilityContext: context,
            as: DockStreamUpdateDTO.self
        )
    }

    public func updates() -> AsyncThrowingStream<DockStreamUpdateDTO, Error> {
        updateStream
    }

    public func close() async {
        notificationTask?.cancel()
        updateContinuation.finish()
        await client.disconnect()
    }
}

import Combine
import Foundation

enum DockScreenState: Equatable, Sendable {
    case configurationError(String)
    case idle([DockHostViewModel])
    case loading([DockHostViewModel])
    case loaded(DockRenderSnapshot)
}

@MainActor
final class DockScreenStore: ObservableObject {
    @Published private(set) var state: DockScreenState
    @Published private(set) var options: DockProjectionOptions
    @Published private(set) var searchText: String
    @Published private(set) var actionError: String?

    private let coalescer: RenderCoalescer<DockRenderSnapshot>
    private let now: @Sendable () -> Date
    private var renderTask: Task<Void, Never>?
    private var searchDebounceTask: Task<Void, Never>?
    private var latestRevision = RenderRevision.zero

    init(
        hosts: [DockHostViewModel],
        options: DockProjectionOptions = DockProjectionOptions(),
        coalescer: RenderCoalescer<DockRenderSnapshot> = RenderCoalescer<DockRenderSnapshot>(),
        now: @escaping @Sendable () -> Date = Date.init
    ) {
        self.state = .idle(hosts)
        self.options = options
        self.searchText = options.searchText
        self.coalescer = coalescer
        self.now = now
        self.actionError = nil
    }

    init(configurationError message: String) {
        self.state = .configurationError(message)
        self.options = DockProjectionOptions()
        self.searchText = ""
        self.coalescer = RenderCoalescer<DockRenderSnapshot>()
        self.now = Date.init
        self.actionError = nil
    }

    deinit {
        renderTask?.cancel()
        searchDebounceTask?.cancel()
    }

    func start() {
        guard renderTask == nil else {
            return
        }

        renderTask = Task { [weak self, coalescer] in
            let stream = await coalescer.stream()
            for await renderSnapshot in stream {
                await MainActor.run {
                    self?.state = .loaded(renderSnapshot)
                }
            }
        }
    }

    func stop() {
        renderTask?.cancel()
        renderTask = nil
        searchDebounceTask?.cancel()
        searchDebounceTask = nil
    }

    func setLoading(hosts: [DockHostViewModel]) {
        state = .loading(hosts)
    }

    func setIdle(hosts: [DockHostViewModel]) {
        state = .idle(hosts)
    }

    func setConfigurationError(_ message: String) {
        state = .configurationError(message)
    }

    func setActionError(_ message: String?) {
        actionError = message
    }

    func setLens(_ lens: DockLensID) {
        updateOptions(
            DockProjectionOptions(
                lens: lens,
                searchText: searchText,
                filters: options.filters
            ),
            syncSearchText: false
        )
    }

    func setSearchText(_ searchText: String) {
        self.searchText = searchText
        searchDebounceTask?.cancel()
        searchDebounceTask = Task { [weak self] in
            do {
                try await Task.sleep(
                    for: .milliseconds(CodexDockConstants.Rendering.searchDebounceMilliseconds)
                )
            } catch {
                return
            }
            await MainActor.run {
                self?.applySearchText(searchText)
            }
        }
    }

    private func applySearchText(_ searchText: String) {
        searchDebounceTask = nil
        updateOptions(
            DockProjectionOptions(
                lens: options.lens,
                searchText: searchText,
                filters: options.filters
            )
        )
    }

    func setFilters(_ filters: DockFilterState) {
        updateOptions(
            DockProjectionOptions(
                lens: options.lens,
                searchText: searchText,
                filters: filters
            ),
            syncSearchText: false
        )
    }

    func updateOptions(_ options: DockProjectionOptions, syncSearchText: Bool = true) {
        self.options = options
        if syncSearchText {
            searchText = options.searchText
        }
        guard case .loaded(let renderSnapshot) = state else {
            return
        }
        enqueueProjection(snapshot: renderSnapshot.snapshot)
    }

    func publish(snapshot: DockSnapshot) {
        enqueueProjection(snapshot: snapshot)
    }

    private func enqueueProjection(snapshot: DockSnapshot) {
        latestRevision = latestRevision.next()
        let revision = latestRevision
        let options = self.options
        let now = self.now
        let coalescer = self.coalescer
        if snapshot.rows.count > CodexDockConstants.Rendering.maxDockRowsPerMainPublish {
            DockLog.rendering.warning("dock render input exceeds main publish row budget rows=\(snapshot.rows.count, privacy: .public) budget=\(CodexDockConstants.Rendering.maxDockRowsPerMainPublish, privacy: .public)")
        }

        Task.detached(priority: .userInitiated) {
            let signpostState = DockSignpost.rendering.beginInterval(RenderSignpostName.dockRenderProject)
            defer {
                DockSignpost.rendering.endInterval(RenderSignpostName.dockRenderProject, signpostState)
            }
            let renderSnapshot = DockRenderProjector(now: now).render(
                snapshot: snapshot,
                options: options,
                revision: revision
            )
            await coalescer.submit(renderSnapshot, revision: revision)
        }
    }
}

    let startedAt = Date()
    let signpostState = DockSignpost.dock.beginInterval("dock.reload")
    DockLog.dock.notice("dock stream reload started hosts=\(self.hosts.count, privacy: .public) show_loading=\(showLoading, privacy: .public)")
    isLoading = true
    defer {
        DockSignpost.dock.endInterval("dock.reload", signpostState)
        isLoading = false
    }

    let hostViewModels = hosts.map(DockHostViewModel.init)
    if showLoading {
        state = .loading(hostViewModels)
        screenStore.setLoading(hosts: hostViewModels)
        publishConnectivity(for: state)
    }

    do {
        localMetadata = try await metadataEngine.load()
        DockLog.persistence.debug("dock metadata loaded entries=\(self.localMetadata.count, privacy: .public)")
    } catch {
        localMetadata = [:]
        await metadataEngine.replace(localMetadata)
        DockLog.persistence.warning("dock metadata load failed error=\(DockLog.errorSummary(error), privacy: .public)")
    }

    await dataEngine?.updateLocalMetadata(localMetadata)
    await dataEngine?.ensureHosts()
    await synchronizeStreams()
    await publishSnapshot()
    if case let .loaded(snapshot) = state {
        DockLog.dock.notice("dock stream reload finished hosts=\(self.hosts.count, privacy: .public) rows=\(snapshot.rowCount, privacy: .public) duration_ms=\(DockLog.milliseconds(since: startedAt), privacy: .public)")
    }
}

private func synchronizeStreams() async {
    let validHostIDs = Set(hosts.map(\.id))
    for hostID in streamConnections.keys where !validHostIDs.contains(hostID) {
        streamTasks[hostID]?.cancel()
        streamTasks[hostID] = nil
        let connection = streamConnections.removeValue(forKey: hostID)
        await connection?.close()
    }

    for host in hosts {
        if let connection = streamConnections[host.id] {
            await resync(host: host, connection: connection)
        } else {
            await openStream(host: host)
        }
    }
}

private func openStream(host: DockHostConfiguration) async {
    guard let dataEngine else {
        return
    }

    await dataEngine.markChecking(host: host)
    await publishSnapshot()
    var openedConnection: (any DockStreamConnection)?
    do {
        let connection = try await streamClient.connect(to: host)
        openedConnection = connection
        streamConnections[host.id] = connection
        let snapshot = try await connection.subscribe()
        try await applySubscribedSnapshot(snapshot, host: host, connection: connection)
        startUpdateTask(host: host, connection: connection)
        await publishSnapshot()
    } catch {
        streamTasks[host.id]?.cancel()
        streamTasks[host.id] = nil
        streamConnections[host.id] = nil
        await openedConnection?.close()
        DockLog.dock.warning("dock stream open failed host_id=\(host.id, privacy: .public) error=\(DockLog.errorSummary(error), privacy: .public)")
        await dataEngine.markFailure(Self.mapLoadFailure(error), host: host)
        await publishSnapshot()
    }
}

private func resync(host: DockHostConfiguration, connection: any DockStreamConnection) async {
    guard let dataEngine else {
        return
    }

    do {
        let snapshot = try await connection.resync()
        try await applyResyncSnapshot(snapshot, host: host)
        await publishSnapshot()
        let rowCount = await dataEngine.rowCount(for: host)
        DockLog.dock.notice("dock stream resync finished host_id=\(host.id, privacy: .public) seq=\(snapshot.seq, privacy: .public) rows=\(rowCount, privacy: .public)")
    } catch {
        DockLog.dock.warning("dock stream resync failed host_id=\(host.id, privacy: .public) error=\(DockLog.errorSummary(error), privacy: .public)")
        await dataEngine.markFailure(Self.mapLoadFailure(error), host: host)
        await publishSnapshot()
    }
}

private func startUpdateTask(host: DockHostConfiguration, connection: any DockStreamConnection) {
    streamTasks[host.id]?.cancel()
    streamTasks[host.id] = Task { [weak self, host, connection] in
        do {
            for try await update in connection.updates() {
                await self?.handleStreamUpdate(update, host: host, connection: connection)
            }
            if !Task.isCancelled {
                await self?.handleStreamFailure(
                    DockLoadFailure.offline("Relay stream closed"),
                    host: host,
                    connection: connection
                )
            }
        } catch is CancellationError {
            return
        } catch {
            await self?.handleStreamFailure(error, host: host, connection: connection)
        }
    }
}

private func handleStreamUpdate(
    _ update: DockStreamUpdateDTO,
    host: DockHostConfiguration,
    connection: any DockStreamConnection
) async {
    guard let dataEngine else {
        return
    }

    let result = await dataEngine.applyUpdate(update, host: host)
    if case .needsResync(let reason) = result {
        DockLog.dock.warning("dock stream resync needed host_id=\(host.id, privacy: .public) reason=\(reason.rawValue, privacy: .public) update_kind=\(update.kind.rawValue, privacy: .public) seq=\(update.seq, privacy: .public)")
        await resync(host: host, connection: connection)
    } else {
        await publishSnapshot()
        let rowCount = await dataEngine.rowCount(for: host)
        DockLog.dock.info("dock stream update applied host_id=\(host.id, privacy: .public) update_kind=\(update.kind.rawValue, privacy: .public) seq=\(update.seq, privacy: .public) rows=\(rowCount, privacy: .public)")
        if let freshness = update.freshness,
           freshness.status != .fresh,
           rowCount > 0 {
            DockLog.dock.notice("dock stream rows retained host_id=\(host.id, privacy: .public) freshness=\(freshness.status.rawValue, privacy: .public) rows=\(rowCount, privacy: .public)")
        }
    }
}

private func applySubscribedSnapshot(
    _ snapshot: DockStreamUpdateDTO,
    host: DockHostConfiguration,
    connection: any DockStreamConnection
) async throws {
    guard let dataEngine else {
        return
    }

    switch await dataEngine.applySnapshot(snapshot, host: host) {
    case .applied:
        return
    case .needsResync(let reason):
        DockLog.dock.warning("dock stream subscribe snapshot rejected host_id=\(host.id, privacy: .public) reason=\(reason.rawValue, privacy: .public) seq=\(snapshot.seq, privacy: .public)")
        let resynced = try await connection.resync()
        try await applyResyncSnapshot(resynced, host: host)
    }
}

private func applyResyncSnapshot(
    _ snapshot: DockStreamUpdateDTO,
    host: DockHostConfiguration
) async throws {
    guard let dataEngine else {
        return
    }

    switch await dataEngine.applySnapshot(snapshot, host: host) {
    case .applied:
        return
    case .needsResync(let reason):
        throw DockLoadFailure.error("Dock stream resync returned incompatible data (\(reason.rawValue)).")
    }
}

private func handleStreamFailure(
    _ error: Error,
    host: DockHostConfiguration,
    connection: any DockStreamConnection
) async {
    DockLog.dock.warning("dock stream update failed host_id=\(host.id, privacy: .public) error=\(DockLog.errorSummary(error), privacy: .public)")
    streamConnections[host.id] = nil
    streamTasks[host.id] = nil
    await connection.close()
    await dataEngine?.markFailure(Self.mapLoadFailure(error), host: host)
    await publishSnapshot()
    let rowCount = await dataEngine?.rowCount(for: host) ?? 0
    if rowCount > 0 {
        DockLog.dock.notice("dock stream rows retained host_id=\(host.id, privacy: .public) freshness=offline rows=\(rowCount, privacy: .public)")
    }
    scheduleReconnect(host: host)
}

private func scheduleReconnect(host: DockHostConfiguration) {
    guard hosts.contains(where: { $0.id == host.id }) else {
        return
    }
    streamTasks[host.id] = Task { [weak self, host] in
        do {
            try await Task.sleep(for: self?.streamReconnectDelay ?? CodexDockConstants.Dock.autoRefreshInterval)
        } catch {
            return
        }
        await self?.openStream(host: host)
    }
}

import Combine
import Foundation

@MainActor
public final class DockStore: ObservableObject {
    public static let defaultAutoRefreshInterval: Duration = CodexDockConstants.Dock.autoRefreshInterval

    @Published public private(set) var state: DockStoreState
    @Published public private(set) var actionError: String?

    let screenStore: DockScreenStore

    private var hosts: [DockHostConfiguration]
    private let streamClient: any DockStreamConnecting
    private let commandEngine: ClientCommandEngine
    private let metadataEngine: LocalMetadataEngine
    private let now: @Sendable () -> Date
    private let streamReconnectDelay: Duration
    private var dataEngine: DockDataEngine?
    private var streamConnections: [String: any DockStreamConnection] = [:]
    private var streamTasks: [String: Task<Void, Never>] = [:]
    private var isLoading = false
    private var localMetadata: [LocalThreadMetadataKey: LocalThreadMetadata] = [:]
    private weak var connectivityReporter: (any AppConnectivityReporting)?
    private let connectivityEventSink: ConnectivityEventSink?

    public var hostConfiguration: DockHostConfiguration? {
        hosts.first
    }

    public func hostConfiguration(for hostID: String) -> DockHostConfiguration? {
        hosts.first { $0.id == hostID }
    }

    public init(
        host: DockHostConfiguration,
        streamClient: any DockStreamConnecting = AppServerDockStreamClient(),
        archiver: any DockSessionArchiving = AppServerDockClient(),
        metadataStore: any LocalThreadMetadataStoring = FileLocalThreadMetadataStore(),
        streamReconnectDelay: Duration = CodexDockConstants.Dock.autoRefreshInterval,
        connectivityEventSink: ConnectivityEventSink? = nil,
        now: @escaping @Sendable () -> Date = Date.init
    ) {
        let hostViewModels = [DockHostViewModel(host: host)]
        self.hosts = [host]
        self.streamClient = streamClient
        self.commandEngine = ClientCommandEngine(archiver: archiver)
        self.metadataEngine = LocalMetadataEngine(store: metadataStore, now: now)
        self.streamReconnectDelay = streamReconnectDelay
        self.connectivityEventSink = connectivityEventSink
        self.now = now
        self.screenStore = DockScreenStore(hosts: hostViewModels, now: now)
        if let registry = try? HostRegistry(hosts: [host]) {
            self.dataEngine = DockDataEngine(registry: registry)
        } else {
            self.dataEngine = nil
        }
        self.state = .idle(hostViewModels)
        self.screenStore.start()
    }

    public init(
        registry: HostRegistry,
        streamClient: any DockStreamConnecting = AppServerDockStreamClient(),
        archiver: any DockSessionArchiving = AppServerDockClient(),
        metadataStore: any LocalThreadMetadataStoring = FileLocalThreadMetadataStore(),
        streamReconnectDelay: Duration = CodexDockConstants.Dock.autoRefreshInterval,
        connectivityEventSink: ConnectivityEventSink? = nil,
        now: @escaping @Sendable () -> Date = Date.init
    ) {
        let hostViewModels = registry.hosts.map(DockHostViewModel.init)
        self.hosts = registry.hosts
        self.streamClient = streamClient
        self.commandEngine = ClientCommandEngine(archiver: archiver)
        self.metadataEngine = LocalMetadataEngine(store: metadataStore, now: now)
        self.streamReconnectDelay = streamReconnectDelay
        self.connectivityEventSink = connectivityEventSink
        self.now = now
        self.screenStore = DockScreenStore(hosts: hostViewModels, now: now)
        self.dataEngine = DockDataEngine(registry: registry)
        self.state = .idle(hostViewModels)
        self.screenStore.start()
    }

    public init(
        configurationError error: Error,
        streamClient: any DockStreamConnecting = AppServerDockStreamClient(),
        archiver: any DockSessionArchiving = AppServerDockClient(),
        metadataStore: any LocalThreadMetadataStoring = FileLocalThreadMetadataStore(),
        streamReconnectDelay: Duration = CodexDockConstants.Dock.autoRefreshInterval,
        connectivityEventSink: ConnectivityEventSink? = nil,
        now: @escaping @Sendable () -> Date = Date.init
    ) {
        let message = error.localizedDescription
        self.hosts = []
        self.streamClient = streamClient
        self.commandEngine = ClientCommandEngine(archiver: archiver)
        self.metadataEngine = LocalMetadataEngine(store: metadataStore, now: now)
        self.streamReconnectDelay = streamReconnectDelay
        self.connectivityEventSink = connectivityEventSink
        self.now = now
        self.screenStore = DockScreenStore(configurationError: message)
        self.dataEngine = nil
        self.state = .configurationError(message)
        self.screenStore.start()
    }

    deinit {
        streamTasks.values.forEach { $0.cancel() }
    }

    public func updateRegistry(_ registry: HostRegistry) async {
        await closeStreams()
        hosts = registry.hosts
        if let dataEngine {
            await dataEngine.updateRegistry(registry)
        } else {
            dataEngine = DockDataEngine(registry: registry)
        }
        setActionError(nil)
        let hostViewModels = registry.hosts.map(DockHostViewModel.init)
        state = .idle(hostViewModels)
        screenStore.setIdle(hosts: hostViewModels)
        publishConnectivity(for: state)
        await reload(showLoading: true)
    }

    public func setConnectivityReporter(_ reporter: (any AppConnectivityReporting)?) {
        connectivityReporter = reporter
        guard connectivityEventSink == nil else {
            return
        }
        reporter?.reportDockState(state)
    }

    private func setActionError(_ message: String?) {
        actionError = message
        screenStore.setActionError(message)
    }

    public func load() async {
        await reload(showLoading: true)
    }

    public func refresh() async {
        await reload(showLoading: false)
    }

    public func setLabel(_ label: String?, for row: DockRowViewModel) async {
        await persistMetadataChange(
            logLabel: "label",
            hostID: row.id.hostID,
            threadID: row.id.threadID
        ) {
            try await metadataEngine.setLabel(label, for: row.metadataKey)
        }
    }

    public func setRail(_ rail: DockRowRail?, for row: DockRowViewModel) async {
        await persistMetadataChange(
            logLabel: "rail",
            hostID: row.id.hostID,
            threadID: row.id.threadID
        ) {
            try await metadataEngine.setRail(rail, for: row.metadataKey)
        }
    }

    public func setPinned(_ isPinned: Bool, for row: DockRowViewModel) async {
        await persistMetadataChange(
            logLabel: isPinned ? "pin" : "unpin",
            hostID: row.id.hostID,
            threadID: row.id.threadID
        ) {
            try await metadataEngine.setPinned(isPinned, for: row)
        }
    }

    public func reorderPinnedRows(_ visibleRowsInNewOrder: [DockRowViewModel]) async {
        await persistMetadataChange(
            logLabel: "reorder_pinned",
            hostID: nil,
            threadID: nil
        ) {
            try await metadataEngine.reorderPinnedRows(visibleRowsInNewOrder)
        }
    }

    @discardableResult
    public func archive(_ row: DockRowViewModel) async -> Bool {
        guard let host = hostConfiguration(for: row.id.hostID) else {
            DockLog.dock.error("dock archive skipped missing host_id=\(row.id.hostID, privacy: .public) thread_id=\(DockLog.publicID(row.id.threadID), privacy: .public)")
            setActionError("Host \(row.id.hostID) is no longer configured.")
            return false
        }

        do {
            DockLog.dock.notice("dock archive action started host_id=\(host.id, privacy: .public) thread_id=\(DockLog.publicID(row.id.threadID), privacy: .public)")
            try await commandEngine.archive(row, on: host)
            setActionError(nil)
            await refresh()
            DockLog.dock.notice("dock archive action finished host_id=\(host.id, privacy: .public) thread_id=\(DockLog.publicID(row.id.threadID), privacy: .public)")
            return true
        } catch {
            DockLog.dock.error("dock archive action failed host_id=\(host.id, privacy: .public) thread_id=\(DockLog.publicID(row.id.threadID), privacy: .public) error=\(DockLog.errorSummary(error), privacy: .public)")
            setActionError(error.localizedDescription)
            return false
        }
    }

    private func reload(showLoading: Bool) async {
        guard !hosts.isEmpty else {
            DockLog.dock.warning("dock reload skipped reason=no_hosts")
            return
        }
        guard !isLoading else {
            DockLog.dock.debug("dock reload skipped reason=already_loading")
            return
        }

import Foundation

struct DockProjectionOptions: Equatable, Sendable {
    let lens: DockLensID
    let searchText: String
    let filters: DockFilterState

    init(
        lens: DockLensID = .newest,
        searchText: String = "",
        filters: DockFilterState = .default
    ) {
        self.lens = lens
        self.searchText = searchText
        self.filters = filters
    }
}

struct DockSessionProjection: Equatable, Sendable {
    let lens: DockLensID
    let pinnedRows: [DockRowViewModel]
    let allPinnedRows: [DockRowViewModel]
    let pinnedSummary: DockPinnedSummary
    let rows: [DockRowViewModel]
    let groups: [DockProjectionGroupViewModel]
    let summary: DockProjectionSummary
    let hiddenCounts: DockProjectionHiddenCounts
    let availableFacets: DockProjectionFacets
    let emptyReason: DockProjectionEmptyReason?
    let isPartial: Bool
    let checkingHostCount: Int
}

extension DockSnapshot {
    func project(options: DockProjectionOptions) -> DockSessionProjection {
        DockSessionProjectionProjector(snapshot: self, options: options).project()
    }
}

private struct DockSessionProjectionProjector {
    let snapshot: DockSnapshot
    let options: DockProjectionOptions

    func project() -> DockSessionProjection {
        let searchedRows = snapshot.rows.filter(matchesSearch)
        let filteredIgnoringIdle = searchedRows.filter(matchesNonIdleFilters)
        let pinnedRows = filteredIgnoringIdle.filter(\.isPinned).sorted(by: pinnedRowPrecedes)
        let hiddenIdleRows = options.filters.showsIdle
            ? []
            : filteredIgnoringIdle.filter { !$0.isPinned && $0.status == .idle }
        let hiddenIdleCount = hiddenIdleRows.count
        let bodyRows = filteredIgnoringIdle
            .filter { !$0.isPinned }
            .filter { options.filters.showsIdle || $0.status != .idle }
            .sorted(by: rowPrecedesByRecency)
        let visibleRows = (pinnedRows + bodyRows).sorted(by: rowPrecedesByRecency)
        let allPinnedRows = snapshot.rows.filter(\.isPinned).sorted(by: pinnedRowPrecedes)
        let groups = groups(for: bodyRows, hiddenIdleRows: hiddenIdleRows)
        let emptyReason = visibleRows.isEmpty ? emptyReason(searchedRows: searchedRows, hiddenIdleCount: hiddenIdleCount) : nil

        return DockSessionProjection(
            lens: options.lens,
            pinnedRows: pinnedRows,
            allPinnedRows: allPinnedRows,
            pinnedSummary: DockPinnedSummary(
                visibleCount: pinnedRows.count,
                totalCount: allPinnedRows.count,
                hiddenByScopeCount: max(0, allPinnedRows.count - pinnedRows.count)
            ),
            rows: options.lens == .newest ? bodyRows : [],
            groups: groups,
            summary: summary(for: visibleRows),
            hiddenCounts: DockProjectionHiddenCounts(idle: hiddenIdleCount),
            availableFacets: availableFacets(),
            emptyReason: emptyReason,
            isPartial: snapshot.isPartial,
            checkingHostCount: snapshot.hostStates.filter { $0.status == .checking }.count
        )
    }

    private func groups(
        for rows: [DockRowViewModel],
        hiddenIdleRows: [DockRowViewModel]
    ) -> [DockProjectionGroupViewModel] {
        switch options.lens {
        case .newest:
            return []
        case .host:
            return hostGroups(for: rows, hiddenIdleRows: hiddenIdleRows)
        case .branch:
            return branchGroups(for: rows, hiddenIdleRows: hiddenIdleRows)
        }
    }

    private func hostGroups(
        for rows: [DockRowViewModel],
        hiddenIdleRows: [DockRowViewModel]
    ) -> [DockProjectionGroupViewModel] {
        let rowsByHost = Dictionary(grouping: rows, by: \.id.hostID)
        let hiddenIdleRowsByHost = Dictionary(grouping: hiddenIdleRows, by: \.id.hostID)
        let stateByHost = Dictionary(uniqueKeysWithValues: snapshot.hostStates.map { ($0.host.id, $0) })
        return snapshot.hosts.compactMap { host in
            if !options.filters.selectedHostIDs.isEmpty,
               !options.filters.selectedHostIDs.contains(host.id) {
                return nil
            }

            let hostRows = (rowsByHost[host.id] ?? []).sorted(by: rowPrecedesByRecency)
            let hiddenIdleCount = hiddenIdleRowsByHost[host.id]?.count ?? 0
            let hostState = stateByHost[host.id]
            let isUnavailable = hostState?.status.isUnavailable ?? false
            guard !hostRows.isEmpty || hiddenIdleCount > 0 || isUnavailable || hostState?.status == .checking else {
                return nil
            }

            return DockProjectionGroupViewModel(
                id: "host::\(host.id)",
                kind: .host,
                title: host.displayName,
                subtitle: hostState?.status.subtitle ?? "\(hostRows.count) sessions",
                rows: hostRows,
                hostIDs: [host.id],
                newestActivityDate: hostRows.map(\.lastActivityDate).max(),
                runningCount: hostRows.filter { $0.status == .running }.count,
                hiddenIdleCount: hiddenIdleCount,
                isUnavailable: isUnavailable,
                unavailableMessage: hostState?.status.unavailableMessage
            )
        }
        .sorted(by: groupPrecedes)
    }

    private func branchGroups(
        for rows: [DockRowViewModel],
        hiddenIdleRows: [DockRowViewModel]
    ) -> [DockProjectionGroupViewModel] {
        let groupedRows = Dictionary(grouping: rows, by: \.branch)
        let hiddenIdleCountsByBranch = Dictionary(grouping: hiddenIdleRows, by: \.branch)
            .mapValues(\.count)
        return groupedRows.map { branch, rows in
            let sortedRows = rows.sorted(by: rowPrecedesByRecency)
            let hostNames = Set(sortedRows.map(\.hostDisplayName)).sorted()
            return DockProjectionGroupViewModel(
                id: "branch::\(branch)",
                kind: .branch,
                title: branch,
                subtitle: "\(sortedRows.count) sessions · \(hostNames.joined(separator: ", "))",
                rows: sortedRows,
                hostIDs: Set(sortedRows.map(\.id.hostID)).sorted(),
                newestActivityDate: sortedRows.map(\.lastActivityDate).max(),
                runningCount: sortedRows.filter { $0.status == .running }.count,
                hiddenIdleCount: hiddenIdleCountsByBranch[branch] ?? 0,
                isUnavailable: false,
                unavailableMessage: nil
            )
        }
        .sorted(by: groupPrecedes)
    }

    private func summary(for rows: [DockRowViewModel]) -> DockProjectionSummary {
        var parts: [String] = ["\(rows.count.formatted()) shown"]
        parts.append(hostSummaryText)
        parts.append(branchSummaryText)
        parts.append(statusSummaryText)
        parts.append(repositorySummaryText)
        parts.append("Source: \(options.filters.source.label)")
        parts.append(options.filters.showsIdle ? "Idle shown" : "Idle hidden")

        let query = normalizedQuery(options.searchText)
        if !query.isEmpty {
            parts.append("Search: \(query)")
        }
        if snapshot.isPartial {
            parts.append("Partial")
        }

        return DockProjectionSummary(
            text: parts.joined(separator: " · "),
            activeFilterCount: options.filters.activeFilterCount + (query.isEmpty ? 0 : 1),
            resultCount: rows.count
        )
    }

    private var hostSummaryText: String {
        guard !options.filters.selectedHostIDs.isEmpty else {
            return "Hosts: Any"
        }
        if options.filters.selectedHostIDs.count == 1,
           let hostID = options.filters.selectedHostIDs.first {
            return "Host: \(hostName(for: hostID))"
        }
        return "Hosts: \(options.filters.selectedHostIDs.count)"
    }

    private var branchSummaryText: String {
        guard !options.filters.selectedBranches.isEmpty else {
            return "Branches: Any"
        }
        if options.filters.selectedBranches.count == 1,
           let branch = options.filters.selectedBranches.first {
            return "Branch: \(branch)"
        }
        return "Branches: \(options.filters.selectedBranches.count)"
    }

    private var statusSummaryText: String {
        let allStatuses = Set(DockRowStatusKind.allCases)
        guard options.filters.statusKinds != allStatuses else {
            return "Status: Any"
        }
        if options.filters.statusKinds.count == 1,
           let status = options.filters.statusKinds.first {
            return "Status: \(status.label)"
        }
        return "Statuses: \(options.filters.statusKinds.count)"
    }

    private var repositorySummaryText: String {
        let query = normalizedQuery(options.filters.repositoryQuery)
        let selectedCount = options.filters.selectedRepositories.count
        if selectedCount == 0, query.isEmpty {
            return "Repo: Any"
        }
        if selectedCount == 1,
           query.isEmpty,
           let repository = options.filters.selectedRepositories.first {
            return "Repo: \(repository)"
        }
        if selectedCount == 0 {
            return "Repo search: \(query)"
        }
        if query.isEmpty {
            return "Repos: \(selectedCount)"
        }
        return "Repos: \(selectedCount), search: \(query)"
    }

    private func availableFacets() -> DockProjectionFacets {
        DockProjectionFacets(
            hosts: snapshot.hosts,
            branches: uniqueSorted(snapshot.rows.map(\.branch)),
            statuses: DockRowStatusKind.allCases.filter { status in
                snapshot.rows.contains { $0.status == status }
            },
            repositories: uniqueSorted(snapshot.rows.map(\.repository)),
            sources: DockSourceFilter.allCases.filter { source in
                source == .any || snapshot.rows.contains { source.includes($0.origin) }
            }
        )
    }

    private func hostName(for hostID: String) -> String {
        snapshot.hosts.first { $0.id == hostID }?.displayName ?? hostID
    }

    private func emptyReason(
        searchedRows: [DockRowViewModel],
        hiddenIdleCount: Int
    ) -> DockProjectionEmptyReason {
        if snapshot.rows.isEmpty {

        if snapshot.rows.isEmpty {
            return .noData
        }
        if hiddenIdleCount > 0 {
            return .idleHidden
        }
        if !normalizedQuery(options.searchText).isEmpty, searchedRows.isEmpty {
            return .noSearchMatches
        }
        if selectedHostsAreUnavailable {
            return .hostUnavailable
        }
        return .noFilterMatches
    }

    private var selectedHostsAreUnavailable: Bool {
        guard !options.filters.selectedHostIDs.isEmpty else {
            return false
        }
        let states = snapshot.hostStates.filter { options.filters.selectedHostIDs.contains($0.host.id) }
        return !states.isEmpty && states.allSatisfy(\.status.isUnavailable)
    }

    private func matchesNonIdleFilters(_ row: DockRowViewModel) -> Bool {
        if !options.filters.selectedHostIDs.isEmpty,
           !options.filters.selectedHostIDs.contains(row.id.hostID) {
            return false
        }
        if !options.filters.selectedBranches.isEmpty,
           !options.filters.selectedBranches.contains(where: { selected in
               row.branch.compare(selected, options: [.caseInsensitive, .diacriticInsensitive]) == .orderedSame
           }) {
            return false
        }
        if !options.filters.statusKinds.contains(row.status) {
            return false
        }
        if !options.filters.selectedRepositories.isEmpty,
           !options.filters.selectedRepositories.contains(row.repository) {
            return false
        }
        let repositoryQuery = normalizedQuery(options.filters.repositoryQuery)
        if !repositoryQuery.isEmpty,
           !row.repository.localizedCaseInsensitiveContains(repositoryQuery) {
            return false
        }
        return options.filters.source.includes(row.origin)
    }

    private func matchesSearch(_ row: DockRowViewModel) -> Bool {
        let query = normalizedQuery(options.searchText)
        guard !query.isEmpty else {
            return true
        }

        return searchableValues(for: row).contains { value in
            value.localizedCaseInsensitiveContains(query)
        }
    }

    private func searchableValues(for row: DockRowViewModel) -> [String] {
        [
            row.title,
            row.hostDisplayName,
            row.id.hostID,
            row.repository,
            row.branch,
            row.summary,
            row.status.label,
            row.label,
            row.origin.automationKind,
            row.id.threadID
        ].compactMap { $0 }
    }

    private func groupPrecedes(_ lhs: DockProjectionGroupViewModel, _ rhs: DockProjectionGroupViewModel) -> Bool {
        let lhsDate = lhs.newestActivityDate ?? Date.distantPast
        let rhsDate = rhs.newestActivityDate ?? Date.distantPast
        if lhsDate != rhsDate {
            return lhsDate > rhsDate
        }

        let titleOrder = lhs.title.localizedCaseInsensitiveCompare(rhs.title)
        if titleOrder != .orderedSame {
            return titleOrder == .orderedAscending
        }
        return lhs.id < rhs.id
    }

    private func rowPrecedesByRecency(_ lhs: DockRowViewModel, _ rhs: DockRowViewModel) -> Bool {
        if lhs.lastActivityDate != rhs.lastActivityDate {
            return lhs.lastActivityDate > rhs.lastActivityDate
        }

        let titleOrder = lhs.title.localizedCaseInsensitiveCompare(rhs.title)
        if titleOrder != .orderedSame {
            return titleOrder == .orderedAscending
        }

        return "\(lhs.id.hostID)::\(lhs.id.threadID)" < "\(rhs.id.hostID)::\(rhs.id.threadID)"
    }

    private func pinnedRowPrecedes(_ lhs: DockRowViewModel, _ rhs: DockRowViewModel) -> Bool {
        if let lhsOrder = lhs.pinnedOrder,
           let rhsOrder = rhs.pinnedOrder,
           lhsOrder != rhsOrder {
            return lhsOrder < rhsOrder
        }
        if lhs.pinnedOrder != nil {
            return true
        }
        if rhs.pinnedOrder != nil {
            return false
        }

        let lhsPinnedAt = lhs.pinnedAt ?? Date.distantPast
        let rhsPinnedAt = rhs.pinnedAt ?? Date.distantPast
        if lhsPinnedAt != rhsPinnedAt {
            return lhsPinnedAt < rhsPinnedAt
        }

        return "\(lhs.id.hostID)::\(lhs.id.threadID)" < "\(rhs.id.hostID)::\(rhs.id.threadID)"
    }

    private func normalizedQuery(_ value: String) -> String {
        value.trimmingCharacters(in: .whitespacesAndNewlines)
    }

    private func uniqueSorted(_ values: [String]) -> [String] {
        Set(values).sorted { lhs, rhs in
            lhs.localizedCaseInsensitiveCompare(rhs) == .orderedAscending
        }
    }
}

