        kind_label TEXT,
        repository TEXT,
        working_directory TEXT,
        branch TEXT,
        updated_at_ms INTEGER,
        summary TEXT,
        message_summary TEXT,
        message_updated_at_ms INTEGER,
        source_kind TEXT,
        archive_state TEXT NOT NULL DEFAULT 'active',
        active_scope_present INTEGER NOT NULL DEFAULT 0,
        archived_scope_present INTEGER NOT NULL DEFAULT 0,
        dock_order INTEGER,
        freshness_status TEXT NOT NULL DEFAULT 'unknown',
        last_seen_at TEXT,
        updated_at TEXT NOT NULL,
        raw_json TEXT,
        PRIMARY KEY (host_id, thread_id),
        FOREIGN KEY (host_id) REFERENCES hosts(host_id) ON DELETE CASCADE
      );

      CREATE TABLE IF NOT EXISTS thread_field_provenance (
        host_id TEXT NOT NULL,
        thread_id TEXT NOT NULL,
        field TEXT NOT NULL,
        source TEXT NOT NULL,
        value_json TEXT,
        updated_at TEXT NOT NULL,
        PRIMARY KEY (host_id, thread_id, field, source)
      );

      CREATE TABLE IF NOT EXISTS sync_scopes (
        host_id TEXT NOT NULL,
        scope TEXT NOT NULL,
        archived INTEGER NOT NULL,
        source_scope TEXT NOT NULL,
        complete INTEGER NOT NULL,
        generation INTEGER NOT NULL DEFAULT 0,
        last_attempt_at TEXT NOT NULL,
        last_sync_at TEXT,
        last_error TEXT,
        PRIMARY KEY (host_id, scope)
      );

      CREATE TABLE IF NOT EXISTS live_leases (
        host_id TEXT NOT NULL,
        thread_id TEXT NOT NULL,
        endpoint_label TEXT,
        endpoint_url TEXT,
        backend_session_id TEXT,
        status TEXT NOT NULL,
        waiting_state TEXT,
        command_capability INTEGER NOT NULL DEFAULT 0,
        validation_at TEXT NOT NULL,
        validation_at_ms INTEGER NOT NULL,
        expires_at_ms INTEGER NOT NULL,
        PRIMARY KEY (host_id, thread_id)
      );

      CREATE TABLE IF NOT EXISTS subscriptions (
        subscription_id TEXT PRIMARY KEY,
        view TEXT NOT NULL,
        host_id TEXT,
        cursor_seq INTEGER NOT NULL DEFAULT 0,
        created_at TEXT NOT NULL,
        updated_at TEXT NOT NULL
      );

      CREATE TABLE IF NOT EXISTS changes (
        seq INTEGER PRIMARY KEY AUTOINCREMENT,
        view TEXT NOT NULL,
        host_id TEXT,
        thread_id TEXT,
        change_type TEXT NOT NULL,
        payload_json TEXT,
        created_at TEXT NOT NULL
      );

      CREATE TABLE IF NOT EXISTS conflicts (
        host_id TEXT NOT NULL,
        thread_id TEXT NOT NULL,
        field TEXT NOT NULL,
        details_json TEXT,
        updated_at TEXT NOT NULL,
        PRIMARY KEY (host_id, thread_id, field)
      );

      CREATE TABLE IF NOT EXISTS turn_cache (
        host_id TEXT NOT NULL,
        thread_id TEXT NOT NULL,
        payload_json TEXT NOT NULL,
        byte_count INTEGER NOT NULL,
        complete INTEGER NOT NULL,
        stop_reason TEXT,
        updated_at TEXT NOT NULL,
        PRIMARY KEY (host_id, thread_id)
      );

      CREATE TABLE IF NOT EXISTS audit_runs (
        audit_id TEXT PRIMARY KEY,
        started_at TEXT NOT NULL,
        completed_at TEXT,
        status TEXT NOT NULL,
        summary_json TEXT
      );

      CREATE TABLE IF NOT EXISTS audit_findings (
        finding_id TEXT PRIMARY KEY,
        audit_id TEXT,
        host_id TEXT,
        thread_id TEXT,
        finding_type TEXT NOT NULL,
        details_json TEXT,
        created_at TEXT NOT NULL
      );

      CREATE INDEX IF NOT EXISTS idx_threads_dock
        ON threads(host_id, active_scope_present, archive_state, dock_order, updated_at_ms DESC);
      CREATE INDEX IF NOT EXISTS idx_threads_archive
        ON threads(host_id, archive_state, updated_at_ms DESC);
      CREATE INDEX IF NOT EXISTS idx_changes_view_seq
        ON changes(view, seq);
    `);

import crypto from "node:crypto";

import {
  RELAY_STATE_DOCK_WINDOW_SIZE,
  RELAY_STATE_SNAPSHOT_SOFT_LIMIT_BYTES,
  RELAY_STATE_UPDATE_SOFT_LIMIT_BYTES,
} from "./dock-relay-constants.mjs";
import {
  buildWindow,
  estimateJSONBytes,
} from "./dock-relay-state-views.mjs";

const DOCK_SUBSCRIBE_METHOD = "dock/subscribe";
const DOCK_RESYNC_METHOD = "dock/resync";
const DOCK_UPDATE_METHOD = "dock/update";

function sequenceFields(store, view) {
  return {
    schemaVersion: 1,
    epoch: view.epoch,
    seq: store.currentSeq(),
    stateGeneration: store.currentSeq(),
  };
}

function dockDeltaClearlyTooLarge(delta) {
  const changedRows = Number(delta.upsertSessions?.length || 0)
    + Number(delta.deleteSessionIDs?.length || 0)
    + Number(delta.upsertHosts?.length || 0);
  return changedRows > RELAY_STATE_DOCK_WINDOW_SIZE;
}

class StateSubscriptionHub {
  constructor({
    store,
    snapshotForView,
    logger = null,
    snapshotSoftLimitBytes = RELAY_STATE_SNAPSHOT_SOFT_LIMIT_BYTES,
    updateSoftLimitBytes = RELAY_STATE_UPDATE_SOFT_LIMIT_BYTES,
  }) {
    this.store = store;
    this.snapshotForView = snapshotForView;
    this.logger = logger;
    this.snapshotSoftLimitBytes = snapshotSoftLimitBytes;
    this.updateSoftLimitBytes = updateSoftLimitBytes;
    this.subscribers = new Set();
    this.epoch = crypto.randomUUID();
  }

  subscribe(listener) {
    const subscriber = {
      id: crypto.randomUUID(),
      listener,
    };
    this.subscribers.add(subscriber);
    return () => {
      this.subscribers.delete(subscriber);
    };
  }

  async snapshot(viewName, options = {}) {
    return this.snapshotForView(viewName, {
      ...options,
      epoch: this.epoch,
      softLimitBytes: this.snapshotSoftLimitBytes,
    });
  }

  dockDelta({
    baseSeq,
    seq,
    freshness,
    upsertHosts = undefined,
    upsertSessions = [],
    deleteSessionIDs = [],
    totalRows,
    complete = undefined,
    window = undefined,
  }) {
    const effectiveWindow = window || (
      complete !== undefined && Number.isFinite(Number(totalRows))
        ? buildWindow({
            offset: 0,
            limit: totalRows,
            rowCount: totalRows,
            totalRows,
          })
        : undefined
    );
    return {
      kind: "delta",
      ...sequenceFields(this.store, this),
      baseSeq,
      seq,
      stateGeneration: seq,
      view: "dock",
      complete,
      totalRows,
      window: effectiveWindow,
      freshness,
      upsertHosts,
      upsertSessions,
      deleteSessionIDs,
    };
  }

  async publishDockDelta(delta) {
    const payloadBytes = dockDeltaClearlyTooLarge(delta)
      ? Number.POSITIVE_INFINITY
      : estimateJSONBytes(delta);
    const update = payloadBytes > this.updateSoftLimitBytes
      ? await this.snapshot("dock")
      : delta;
    for (const subscriber of this.subscribers) {
      try {
        subscriber.listener(update);
      } catch (error) {
        this.logger?.warn?.("state.subscriber_failed", { error });
      }
    }
  }
}

export {
  DOCK_RESYNC_METHOD,
  DOCK_SUBSCRIBE_METHOD,
  DOCK_UPDATE_METHOD,
  StateSubscriptionHub,
};

class NotificationIngestor {
  constructor({
    store,
    hostId,
    scheduleReconciliation,
    logger = null,
  }) {
    this.store = store;
    this.hostId = hostId;
    this.scheduleReconciliation = scheduleReconciliation;
    this.logger = logger;
  }

  ingestArchiveMutation({ threadId, archived }) {
    if (!threadId) {
      return null;
    }
    const result = this.store.applyArchiveMutation({
      hostID: this.hostId,
      threadID: threadId,
      archived,
    });
    this.scheduleReconciliation?.({
      reason: archived ? "thread/archive" : "thread/unarchive",
      immediate: false,
    });
    return result;
  }

  markScopeStale(scopeName, error) {
    this.store.markScopeStale(this.hostId, scopeName, error);
    this.scheduleReconciliation?.({
      reason: "scope-stale",
      immediate: false,
    });
  }

  ingestLiveDisconnect(error = null) {
    this.logger?.warn?.("state.live_disconnect_marked_stale", { error });
    this.markScopeStale("live-leases", error || new Error("live endpoint disconnected"));
  }
}

export {
  NotificationIngestor,
};

